public record ToolExecutionResult(String toolName, String output, long latencyMs) {}

public class AgentToolCoordinator {
    public List<ToolExecutionResult> executeToolsConcurrently(
            List<ToolCallRequest> requests) throws InterruptedException {

        try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
            List<Subtask<ToolExecutionResult>> subtasks = requests.stream()
                .map(req -> scope.fork(() -> invokeToolSafely(req)))
                .toList();

            scope.join();           // Block carrier until all finish
            scope.throwIfFailed();  // Propagate first failure cleanly

            return subtasks.stream()
                .map(Subtask::get)
                .toList();
        }
    }
}

public class CustomerAccountTool {

    public record AccountQuery(
        @Description("Unique 10-digit customer UUID") 
        UUID customerId,
        @Description("Flag to retrieve active credit balance") 
        boolean includeCreditHistory
    ) {}

    @Tool(name = "query_customer_account", 
          description = "Fetches audited account details and risk tier")
    public AccountDetails execute(AccountQuery query) {
        // Strongly-typed inputs directly mapped from LLM JSON
        return accountRepository.findByCustomerId(query.customerId())
            .map(acc -> new AccountDetails(acc.id(), acc.status(), acc.tier()))
            .orElseThrow(() -> new AccountNotFoundException(query.customerId()));
    }
}
